macro_rules! tests {
    () => {
        # [cfg (test)] mod tests { use super :: * ; use std :: io :: Write ; use std :: path :: PathBuf ; use tempfile :: tempdir ; fn setup_test_file (dir : & tempfile :: TempDir , file_name : & str , content : & str) -> PathBuf { let file_path = dir . path () . join (file_name) ; let mut file = fs :: File :: create (& file_path) . unwrap () ; file . write_all (content . as_bytes ()) . unwrap () ; file_path } # [test] fn test_modify_file_adds_prelude_and_removes_uses () -> Result < () > { let dir = tempdir () ? ; let file_path = setup_test_file (& dir , "test_file.rs" , "use std::collections::HashMap;\nuse crate::another_module;\n\nfn main() {}\n" ,) ; modify_file (& file_path , false , true) ? ; let content = fs :: read_to_string (& file_path) ? ; assert ! (content . contains ("use crate::prelude::*;")) ; assert ! (! content . contains ("use std::collections::HashMap;")) ; assert ! (! content . contains ("use crate::another_module;")) ; assert ! (content . contains ("fn main() {}")) ; Ok (()) } # [test] fn test_modify_file_dry_run () -> Result < () > { let dir = tempdir () ? ; let file_path = setup_test_file (& dir , "test_file.rs" , "use std::collections::HashMap;\nfn main() {}\n" ,) ; let original_content = fs :: read_to_string (& file_path) ? ; modify_file (& file_path , true , false) ? ; let content = fs :: read_to_string (& file_path) ? ; assert_eq ! (content , original_content) ; Ok (()) } # [test] fn test_modify_file_no_use_statements () -> Result < () > { let dir = tempdir () ? ; let file_path = setup_test_file (& dir , "test_file.rs" , "fn main() {}\n") ; let original_content = fs :: read_to_string (& file_path) ? ; modify_file (& file_path , false , false) ? ; let content = fs :: read_to_string (& file_path) ? ; assert_eq ! (content , original_content) ; Ok (()) } # [test] fn test_modify_file_no_force_no_overwrite () -> Result < () > { let dir = tempdir () ? ; let file_path = setup_test_file (& dir , "test_file.rs" , "use std::fmt;\nfn some_func() {}\n") ; let original_content = fs :: read_to_string (& file_path) ? ; modify_file (& file_path , false , false) ? ; let content_after_skip = fs :: read_to_string (& file_path) ? ; assert_eq ! (original_content , content_after_skip) ; Ok (()) } # [test] fn test_modify_file_force_overwrite () -> Result < () > { let dir = tempdir () ? ; let file_path = setup_test_file (& dir , "test_file.rs" , "use std::fmt;\nfn some_func() {}\n") ; modify_file (& file_path , false , true) ? ; let first_modified_content = fs :: read_to_string (& file_path) ? ; assert ! (first_modified_content . contains ("use crate::prelude::*;")) ; assert ! (! first_modified_content . contains ("use std::fmt;")) ; modify_file (& file_path , false , true) ? ; let second_modified_content = fs :: read_to_string (& file_path) ? ; assert_eq ! (first_modified_content , second_modified_content) ; Ok (()) } }
    };
}

tests!();